/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { InvalidSlugError, uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizationRetiredSlugs,
  organizations,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * A retired slug still belongs to its workspace while `now` is strictly
 * before `retiredAt + ORG_SLUG_HOLD_DAYS` days. At that instant it is released.
 */
function retiredSlugHeld(retiredAt: string, now: Date): boolean {
  const retiredMs = new Date(retiredAt).getTime();
  if (Number.isNaN(retiredMs)) return false;
  return now.getTime() - retiredMs < ORG_SLUG_HOLD_DAYS * DAY_MS;
}

