/**
 * Resolves a URL slug to a live workspace. The current slug wins. Otherwise a
 * slug this workspace retired still resolves until its hold ends, and the
 * organization returned carries the current slug, not the retired one.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const current = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const now = new Date();
  const retirements = db
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .all()
    .filter((row) => retiredSlugHeld(row.retiredAt, now))
    .sort((a, b) => (a.retiredAt < b.retiredAt ? 1 : -1));

  for (const retirement of retirements) {
    const org = db
      .select()
      .from(organizations)
      .where(
        and(
          eq(organizations.id, retirement.orgId),
          isNull(organizations.archivedAt),
        ),
      )
      .get();
    if (org) return toOrganization(org);
  }

  return null;
}

