/**
 * Replaces `orgId`'s slug with `nextSlug`, which must already have passed the
 * shared slug rules. Refuses a slug another workspace holds, live, deleted,
 * or inside its retirement window. Reclaiming a slug this workspace retired
 * ends that retirement. Renaming to the current slug writes nothing.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  nextSlug: string,
): Promise<{ readonly organization: Organization; readonly changed: boolean }> {
  const db = getDb();
  const retiredAt = toIsoTimestamp(new Date());
  const now = new Date(retiredAt);

  const result = db.transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === nextSlug) {
      return { row: current, changed: false };
    }

    const holder = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(eq(organizations.slug, nextSlug))
      .get();
    if (holder && holder.id !== orgId) {
      throw new InvalidSlugError(nextSlug, "is not available");
    }

    const blocking = tx
      .select()
      .from(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, nextSlug))
      .all()
      .some(
        (row) => row.orgId !== orgId && retiredSlugHeld(row.retiredAt, now),
      );
    if (blocking) {
      throw new InvalidSlugError(nextSlug, "is not available");
    }

    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.orgId, orgId),
          eq(organizationRetiredSlugs.slug, nextSlug),
        ),
      )
      .run();
    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.orgId, orgId),
          eq(organizationRetiredSlugs.slug, current.slug),
        ),
      )
      .run();
    tx.insert(organizationRetiredSlugs)
      .values({
        id: newId(),
        orgId,
        slug: current.slug,
        retiredAt,
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: nextSlug, updatedAt: retiredAt })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    return { row, changed: true };
  });

  return { organization: toOrganization(result.row), changed: result.changed };
}

/** Feeds `uniqueSlug()`; current slugs and slugs still inside their hold. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();
  const now = new Date();
  const taken = new Set<string>();

  const current = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  for (const row of current) taken.add(row.slug);

  const retired = db
    .select({
      slug: organizationRetiredSlugs.slug,
      retiredAt: organizationRetiredSlugs.retiredAt,
    })
    .from(organizationRetiredSlugs)
    .where(like(organizationRetiredSlugs.slug, `${prefix}%`))
    .all();
  for (const row of retired) {
    if (retiredSlugHeld(row.retiredAt, now)) taken.add(row.slug);
  }

  return [...taken];
}

