import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import { PermissionDeniedError } from "@/lib/permissions";
import { activityActionSchema } from "@/schemas/activity";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import * as userRepo from "@/server/repositories/user-repository";
import type { SessionPrincipal } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
  vi.useRealTimers();
});

describe("renameOrganizationSlug", () => {
  it("renames, holds the old slug, audits and emits once", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-03-01T00:00:00.000Z"));
    const tenant = await createTenant("holdme", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    const updated = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "holdme-next",
    });
    off();

    expect(updated.slug).toBe("holdme-next");
    expect(updated.name).toBe(tenant.org.name);
    expect(updated.plan).toBe(tenant.org.plan);
    expect(updated.settings).toEqual(tenant.org.settings);

    const byOld = await resolveOrgBySlug("holdme");
    expect(byOld?.id).toBe(tenant.org.id);
    expect(byOld?.slug).toBe("holdme-next");

    const byNew = await orgRepo.findOrgBySlug("holdme-next");
    expect(byNew?.slug).toBe("holdme-next");

    const summary = await getOrganizationSummary(tenant.actors.admin, tenant.org.id);
    expect(summary.organization.slug).toBe("holdme-next");

    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.slug).toBe("holdme-next");

    const principal: SessionPrincipal = {
      sessionId: "ses" as SessionPrincipal["sessionId"],
      userId: tenant.userIds.member,
      activeOrgId: tenant.org.id,
      expiresAt: tenant.org.createdAt,
    };
    const actor = await resolveActorForOrg(principal, "holdme");
    expect(actor?.orgId).toBe(tenant.org.id);
    const actorNew = await resolveActorForOrg(principal, "holdme-next");
    expect(actorNew?.orgId).toBe(tenant.org.id);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "holdme",
      to: "holdme-next",
    });

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.admin,
      metadata: { from: "holdme", to: "holdme-next" },
    });

    await expect(
      renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "nope-member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("holdme-next");

    const same = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "holdme-next",
    });
    expect(same.updatedAt).toBe(updated.updatedAt);
    const pageAfter = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(pageAfter.items).toHaveLength(1);

    const other = await createTenant("othertenant", "growth");
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "holdme",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(other.org.id))?.slug).toBe("othertenant");

    const user = await userRepo.insertUser({
      email: "creator@hold.test",
      name: "Creator",
      passwordHash: "seed",
    });
    const created = await createOrganization(user.id, {
      name: "Derived",
      slug: "holdme",
      plan: "free",
    });
